"""verdict.md + summary_ko.md for the single-seed 200k long run and its 180k real-data pass (2026-09-08/09). Every number is
read from the JSON artifacts in this directory (results_long_run.json, results_suite_compare_180k.json, results_context.json).
Run: uv run python eval/long_run_2026-09-09/build_verdict.py"""
import json
from pathlib import Path
D = Path(__file__).parent
R = json.loads((D / "results_long_run.json").read_text()); C = json.loads((D / "results_suite_compare_180k.json").read_text()); X = json.loads((D / "results_context.json").read_text())
T = R["trajectory"]; snaps = R["snapshots"]; col = R["collapse"]; best = R["best_val_mse"]
REFS = [("v4_dual_split_ctx_tw4_diff_lam1_lr5e-4_mixed_cell_s0", "dual_split 20k (session 24)"), ("real_ds_lr5e-4_s0", "real_ds 20k"),
        ("v4_ds_none_lam0_lr5e-4_any_cell_bar32_40k_s0", "ds 40k"), ("v4_ds_latinit_lam0_lr5e-4_any_cell_bar32_40k_s0", "latinit 40k (E6)"), ("histgb", "HistGB")]
def cell(ref, k):
    r = C["vs"][ref].get(k); return "–" if r is None else f"{r['wins']}:{r['losses']} (p {r['p_sign']:.3g}, {r['mean_run']:.3f} vs {r['mean_ref']:.3f})"
def q(w, name): r = R[w][name]; return f"{r['rel_drop']*100:+.1f}% (tol {r['tolerance']:.4f}, {'converged' if r['converged'] else 'not converged'})"
L = ["# Verdict: single-seed 200k long run of dual_split (schedule-free, constant lr) and its 180k snapshot on real data",
     "", f"Run `{R['run']}` — {R['steps']} steps, {R['val_records']} validation records; snapshots every 20k on HF `fbdeme/jepa-pfn-ckpt`. Generated by `build_verdict.py`.", "",
     "## 1. Validation trajectory (per 20k snapshot)", "", "| series | " + " | ".join(f"{s//1000}k" for s in snaps) + " |", "|---|" + "---|" * len(snaps)]
for name in ("val_mse", "val_ppd", "val_jepa", "val_tgt.erank", "val_tgt.dim_std", "val_tgt.dim_std_min", "val_pred.erank"):
    L.append(f"| {name} | " + " | ".join(f"{T[name][str(s)]:.3f}" for s in snaps) + " |")
L += ["", f"Best val_mse {best['val_mse']} at step {best['step']} (val_ppd {best['val_ppd']}).", "",
      f"## 2. Collapse (criterion: {col['criterion']})", "",
      f"Onset {col['onset']}, transient recovery {col['recovered']}, collapsed at the last step {col['last_step']}. Last pre-collapse snapshot: {col['last_pre_collapse_snapshot']}.", "",
      "## 3. E7 quarter rule", "", f"Pre-collapse window {R['e7_quarters_pre_collapse']['window']}: val_mse {q('e7_quarters_pre_collapse', 'val_mse')}; val_ppd {q('e7_quarters_pre_collapse', 'val_ppd')}; val_jepa {q('e7_quarters_pre_collapse', 'val_jepa')}.",
      f"Full window {R['e7_quarters_full']['window']}: val_mse {q('e7_quarters_full', 'val_mse')} — the 'converged' verdict on the full window is an artefact of the collapse, not convergence.", "",
      f"## 4. Real data, 180k snapshot (E9 protocol, {C['n_datasets']} datasets, exact sign test per dataset)", "",
      "| reference | clf acc wins:losses | clf auc | reg r² |", "|---|---|---|---|"]
for ref, label in REFS:
    L.append(f"| {label} | {cell(ref, 'clf_acc')} | {cell(ref, 'clf_auc')} | {cell(ref, 'reg_r2')} |")
S = X["same_115_clf"]; G = X["big_vs_base_shared"]
L += ["", "## 5. Context for the HistGB gap (same 115 classification datasets; from the existing suite JSONs)", "",
      f"- Snapshot 180k mean acc {S['snapshot_180k']['mean_acc']} vs paper-prior base_ds 20k {S['base_ds_paper_prior_20k']['mean_acc']} (base_dual {S['base_dual_paper_prior_20k']['mean_acc']}); logreg {S['logreg_this_pass']['mean_acc']} / {S['logreg_paper_pass']['mean_acc']} and HistGB {S['histgb_this_pass']['mean_acc']} / {S['histgb_paper_pass']['mean_acc']} agree across the two passes.",
      f"- Old size ladder on the {G['n_datasets']} shared datasets: big_ds {G['big_ds']['mean_acc']} vs base_ds {G['base_ds']['mean_acc']} (HistGB {G['histgb']['mean_acc']}); {G['big_config']}.",
      f"- Largest gaps to HistGB: " + ", ".join(f"{g['dataset'].split('|')[1]} {g['gap']:.3f}" for g in X["gap_to_histgb"]["largest"]) + f". Snapshot beats HistGB on {X['gap_to_histgb']['snapshot_wins']} / {X['gap_to_histgb']['n']} datasets.", "",
      "## 6. Reading", "",
      "- Long training keeps improving the value metric to the last pre-collapse snapshot and transfers to real data: the snapshot beats ds 40k on all three metrics and ties the E6 latinit 40k arm.",
      "- The latent target collapses to a constant late in the run and takes the value head with it; the snapshot policy (upload every 20k) is what saved the model.",
      "- Not established: whether the gain is the latent term's (needs the same structure with lambda_jepa 0 at matched steps) — ds has 6 blocks, the value path here has 10. Single seed.",
      "- Parameter count is not the first lever against HistGB: the paper-prior base_ds at 20k is above this real-prior run at 180k, the old 34M ladder tied its base, and the largest gaps are multiclass wide-feature datasets (K_FEAT 64 cap, bar-head classification)."]
(D / "verdict.md").write_text("\n".join(L) + "\n")
K = ["# 요약 (생성물, 수치 출처 = 이 디렉토리 JSON)", "",
     f"- 200k 1시드 장기 런: val_mse {T['val_mse'][str(snaps[0])]:.3f}(20k) → {T['val_mse'][str(col['last_pre_collapse_snapshot'])]:.3f}({col['last_pre_collapse_snapshot']//1000}k), 최량 {best['val_mse']} @{best['step']}; 붕괴 onset {col['onset']}, 200k 는 {T['val_mse'][str(snaps[-1])]:.3f}(상수맵 수준).",
     f"- E7 규칙(붕괴 전 창): val_mse {q('e7_quarters_pre_collapse', 'val_mse')}.",
     f"- 180k 실데이터 {C['n_datasets']}셋: vs ds 40k acc {cell('v4_ds_none_lam0_lr5e-4_any_cell_bar32_40k_s0', 'clf_acc')}, vs latinit 40k acc {cell('v4_ds_latinit_lam0_lr5e-4_any_cell_bar32_40k_s0', 'clf_acc')}, vs HistGB acc {cell('histgb', 'clf_acc')}.",
     f"- 맥락: 같은 115셋에서 논문 prior base_ds 20k {S['base_ds_paper_prior_20k']['mean_acc']} > 이번 실데이터 prior 180k {S['snapshot_180k']['mean_acc']}; 옛 34M 사다리 big_ds {G['big_ds']['mean_acc']} ≈ base_ds {G['base_ds']['mean_acc']}(공유 {G['n_datasets']}셋). HistGB 와 가장 벌어진 셋은 다중클래스·넓은 표.",
     "- 미확립: 잠재 항의 몫(V λ_jepa 0 매칭 대조 없음), 시드 1, 붕괴 방지 손잡이 없음."]
(D / "summary_ko.md").write_text("\n".join(K) + "\n")
print("wrote verdict.md, summary_ko.md")
